            cur[int(m.group(1))]=dict(claim=parts[1].strip() if len(parts)>1 else '',status=parts[2].strip() if len(parts)>2 else '',len=len(l),text=l)
    snaps.append(cur)
import pickle
pickle.dump(snaps,open(SP+'/snaps.pkl','wb'))
# detect disappearances and replacement
events=[]
for i in range(1,len(snaps)):
    a,b=snaps[i-1],snaps[i]
    for n in a:
        if n not in b: events.append(('GONE',n,i,commits[i][1]))
