SP=/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/gla; python3 -I - <<EOF
import json,re,collections
rows=json.load(open('$SP/rows3.json'))
HASH=r'\`?[0-9a-f]{9}\`?'
sig=collections.defaultdict(set)
for r in rows:
    st=r['status']; no=r['notes']; cl=r['claim']; t=r['text']
    if st.startswith('FIXED'): sig['status FIXED'].add(r['num'])
    if re.search(r'the fix|fixed|\bfix\b',st,re.I) and not st.startswith('FIXED'): sig['status says fix (not FIXED head)'].add(r['num'])
    if re.search(r'\bfixed '+HASH,no): sig['notes "fixed <hash>"'].add(r['num'])
    if re.search(r'\b(closed|Closed|CLOSED)\b',no): sig['notes "closed"'].add(r['num'])
    if re.search(r'\b(closed|Closed|CLOSED)\b',st): sig['status "closed"'].add(r['num'])
    if re.search(r'\bgated\b',t): sig['"gated" anywhere'].add(r['num'])
    if re.search(r'partly fixed|partly closed|half',st): sig['status partly fixed'].add(r['num'])
    if re.search(r'^\*\*?(CLOSED|FIXED)',cl): sig['claim begins closed'].add(r['num'])
    if re.search(r'XXX',t): sig['XXX anywhere'].add(r['num'])
for k,v in sig.items(): print(k,len(v))
anyclosed=set()
for k in ('status FIXED','status says fix (not FIXED head)','notes "fixed <hash>"','notes "closed"','status "closed"','status partly fixed'): anyclosed|=sig[k]
print('union',len(anyclosed))
print('FIXED but no hash in status:', [r['num'] for r in rows if r['status'].startswith('FIXED') and not re.search(HASH,r['status'])][:30])
# FIXED status forms
fx=collections.Counter(re.sub(r'\`[0-9a-f]{9}\`','<h>',r['status'])[:80] for r in rows if r['status'].startswith('FIXED'))
for k,v in fx.most_common(40): print(v,k)
EOF

